/**
 * @description Inbound calls: checks the caller, the event and the body, records the call as a transaction, runs the
 * event's handler class and answers. A repeated X-Request-Id gets the first answer again.
 * @group Integration Hub
 */
public with sharing class IntegrationHubInbound {

    private static final Integer BODY_MAX = 131072;

    /**
     * @description The answer to the caller.
     */
    public class Response {
        /** @description HTTP status. */
        public Integer statusCode = 200;
        /** @description JSON body. */
        public Map<String, Object> body = new Map<String, Object>();
        /** @description True when this repeats the first answer to the same X-Request-Id. */
        public Boolean replay = false;
    }

    /**
     * @description One inbound request.
     */
    public class Request {
        /** @description Event key from the URL. */
        public String eventKey;
        /** @description Raw body. */
        public String body;
        /** @description Request headers. */
        public Map<String, String> headers = new Map<String, String>();
    }

    /**
     * @description Handles an inbound call.
     * @param req the request
     * @return the answer
     */
    public static Response receive(Request req) {
        IH_Event__c ev = inboundEvent(req.eventKey);
        Map<String, Object> data = parseObject(req.body);
        Response refused = refusal(req, ev, data);
        if (refused != null) {
            return refused;
        }
        String requestId = header(req.headers, 'X-Request-Id');
        String key = requestKey(ev.Event_Key__c, requestId);
        IH_Transaction__c earlier = byKey(key);
        if (earlier != null) {
            return replay(earlier);
        }
        IH_Transaction__c t = newTransaction(ev, req, requestId);
        t.Request_Key__c = key;
        try {
            IntegrationHubData.insertAll(new List<IH_Transaction__c>{ t });
        } catch (DmlException e) {
            IH_Transaction__c same = byKey(key);
            return same != null ? replay(same) : answer(500, error(e.getMessage()));
        }
        IntegrationHub.InboundContext ctx = new IntegrationHub.InboundContext();
        ctx.eventKey = ev.Event_Key__c;
        ctx.body = req.body;
        ctx.data = data;
        ctx.headers = req.headers;
        ctx.transactionId = t.Id;
        return run(ev, t, ctx);
    }

    /**
     * @description Active connections whose Inbound User is the running user.
     * @return the connection Ids
     */
    public static Set<Id> callerConnections() {
        return new Map<Id, SObject>(IntegrationHubData.query(
            'SELECT Id FROM IH_Connection__c WHERE Inbound_User__c = :uid AND Active__c = true LIMIT 1000',
            new Map<String, Object>{ 'uid' => UserInfo.getUserId() })).keySet();
    }

    /**
     * @description Parses a JSON object.
     * @param text the JSON text
     * @return the object, or null when the text is blank, invalid or not an object
     */
    public static Map<String, Object> parseObject(String text) {
        try {
            Object parsed = String.isBlank(text) ? null : JSON.deserializeUntyped(text);
            return parsed instanceof Map<String, Object> ? (Map<String, Object>) parsed : null;
        } catch (JSONException e) {
            return null;
        }
    }

    /**
     * @description Builds an answer.
     * @param statusCode the HTTP status
     * @param body the JSON body
     * @return the answer
     */
    public static Response answer(Integer statusCode, Map<String, Object> body) {
        Response r = new Response();
        r.statusCode = statusCode;
        r.body = body;
        return r;
    }

    /**
     * @description An error body.
     * @param message the error text
     * @return the body
     */
    public static Map<String, Object> error(String message) {
        return new Map<String, Object>{ 'status' => IntegrationHub.STATUS_FAILED, 'error' => message };
    }

    /**
     * @description Why a request is refused, in answer order: unknown event 404 (no query), caller not on the event's
     * connection 403, body not a JSON object 400.
     * @param req the request
     * @param ev the inbound event, or null when unknown
     * @param data the parsed body, or null
     * @return the refusal, or null when the request may run
     */
    @TestVisible
    private static Response refusal(Request req, IH_Event__c ev, Map<String, Object> data) {
        if (ev == null) {
            return answer(404, error('Unknown or inactive inbound event: ' + req.eventKey));
        }
        if (!callerConnections().contains(ev.Connection__c)) {
            return answer(403, error('This user may not call ' + ev.Event_Key__c + '.'));
        }
        return data == null ? answer(400, error('The body must be a JSON object.')) : null;
    }

    /**
     * @description The key that makes a repeated X-Request-Id replay the first answer.
     * @param eventKey the event key
     * @param requestId the X-Request-Id header, may be blank
     * @return eventKey:requestId clipped to 255, or null when there is no request Id
     */
    @TestVisible
    private static String requestKey(String eventKey, String requestId) {
        return String.isBlank(requestId) ? null : IntegrationHub.clip(eventKey + ':' + requestId, 255);
    }

    private static IH_Transaction__c newTransaction(IH_Event__c ev, Request req, String requestId) {
        return new IH_Transaction__c(Event__c = ev.Id, Event_Name__c = ev.Event_Key__c,
            Direction__c = IntegrationHub.INBOUND, Status__c = IntegrationHub.STATUS_RECEIVED, Retry_Count__c = 0,
            Request_Payload__c = IntegrationHub.clip(req.body, BODY_MAX), Request_Id__c = IntegrationHub.clip(requestId, 255),
            Caller_User__c = UserInfo.getUserId(), Target_Name__c = ev.Handler_Class__c, Last_Attempt__c = System.now());
    }

    private static Response run(IH_Event__c ev, IH_Transaction__c t, IntegrationHub.InboundContext ctx) {
        Savepoint sp = Database.setSavepoint();
        Response r;
        try {
            IntegrationHub.InboundResult result = ((IntegrationHub.IInboundHandler) IntegrationHub.createInstance(ev.Handler_Class__c)).handle(ctx);
            r = finish(t, result);
        } catch (Exception e) {
            Database.rollback(sp);
            t.Status__c = IntegrationHub.STATUS_FAILED;
            IntegrationHub.setError(t, e.getMessage());
            r = answer(500, new Map<String, Object>{ 'transactionId' => t.Id, 'status' => t.Status__c, 'error' => e.getMessage() });
        }
        t.Http_Status_Code__c = r.statusCode;
        t.Response_Body__c = IntegrationHub.clip(JSON.serialize(r.body), BODY_MAX);
        t.Completed_At__c = System.now();
        IntegrationHubData.updateEach(new List<IH_Transaction__c>{ t });
        return r;
    }

    /**
     * @description Turns the handler's result into the answer and sets the transaction's status (no DML): success 200
     * with the record and data; otherwise the result's code (default 422) with the error.
     * @param t the transaction, in memory
     * @param result the handler result, may be null
     * @return the answer
     */
    @TestVisible
    private static Response finish(IH_Transaction__c t, IntegrationHub.InboundResult result) {
        if (result != null && result.success == true) {
            t.Status__c = IntegrationHub.STATUS_SUCCESS;
            t.Related_Record_Id__c = result.recordId;
            t.Related_Object__c = result.recordId == null ? null : String.valueOf(result.recordId.getSObjectType());
            return answer(200, new Map<String, Object>{
                'transactionId' => t.Id, 'status' => t.Status__c, 'recordId' => result.recordId, 'data' => result.data });
        }
        String message = result == null ? 'The handler returned no result.' : result.message;
        t.Status__c = IntegrationHub.STATUS_FAILED;
        IntegrationHub.setError(t, message);
        Integer code = result == null || result.statusCode == null ? 422 : result.statusCode;
        return answer(code, new Map<String, Object>{ 'transactionId' => t.Id, 'status' => t.Status__c, 'error' => message });
    }

    /**
     * @description The stored first answer for a repeated request.
     * @param t the earlier transaction
     * @return the answer, marked as a replay
     */
    @TestVisible
    private static Response replay(IH_Transaction__c t) {
        Response r = answer(t.Http_Status_Code__c == null ? 200 : t.Http_Status_Code__c.intValue(), parseObject(t.Response_Body__c));
        if (r.body == null) {
            r.body = new Map<String, Object>{ 'transactionId' => t.Id, 'status' => t.Status__c };
        }
        r.replay = true;
        return r;
    }

    private static IH_Event__c inboundEvent(String eventKey) {
        return String.isBlank(eventKey) ? null : (IH_Event__c) IntegrationHubData.queryFirst(
            'SELECT Id, Event_Key__c, Connection__c, Handler_Class__c FROM IH_Event__c '
            + 'WHERE Event_Key__c = :k AND Active__c = true AND Direction__c = :d LIMIT 1',
            new Map<String, Object>{ 'k' => eventKey, 'd' => IntegrationHub.INBOUND });
    }

    private static IH_Transaction__c byKey(String key) {
        return key == null ? null : (IH_Transaction__c) IntegrationHubData.queryFirst(
            'SELECT Id, Status__c, Http_Status_Code__c, Response_Body__c FROM IH_Transaction__c WHERE Request_Key__c = :k LIMIT 1',
            new Map<String, Object>{ 'k' => key });
    }

    /**
     * @description A header value, matched without regard to case.
     * @param headers the headers, may be null
     * @param name the header name
     * @return the value, or null
     */
    @TestVisible
    private static String header(Map<String, String> headers, String name) {
        for (String k : headers == null ? new Set<String>() : headers.keySet()) {
            if (name.equalsIgnoreCase(k)) {
                return headers.get(k);
            }
        }
        return null;
    }
}
